# Extract the members of turn-restriction relations from an OSM .pbf file.
#
# GDAL (and therefore sf / osmextract) only exposes relations as geometries in
# the `other_relations` layer: member ids and roles (from / via / to) are lost.
# osmium-tool reads the PBF directly and can write the filtered relations as
# OPL, a one-line-per-object text format that is trivial to parse in R.
#
# osmium-tool is needed once on the PATH, e.g. (any one of these):
#   pixi global install osmium-tool
#   conda install -c conda-forge osmium-tool
# or pass `osmium = c("pixi", "exec", "-s", "osmium-tool", "osmium")` to run it
# without installing.

# OPL escapes special characters in tags/roles as %<hex codepoint>%
opl_unescape <- function(x) {
  has_esc <- grepl("%[0-9a-fA-F]+%", x)
  x[has_esc] <- vapply(x[has_esc], function(s) {
    m <- gregexpr("%[0-9a-fA-F]+%", s)
    regmatches(s, m) <- lapply(regmatches(s, m), function(codes) {
      intToUtf8(strtoi(gsub("%", "", codes), 16L), multiple = TRUE)
    })
    s
  }, character(1), USE.NAMES = FALSE)
  x
}

# Split "a=1,b=2" style OPL lists into a list of character vectors
opl_split <- function(x) {
  out <- strsplit(x, ",", fixed = TRUE)
  out[is.na(x) | x == ""] <- list(character(0))
  out
}

run_osmium <- function(osmium, args, out) {
  res <- system2(osmium[1], c(osmium[-1], args, "--overwrite", "-o", shQuote(out)),
                 stdout = TRUE, stderr = TRUE)
  if (!is.null(attr(res, "status")) || !file.exists(out)) {
    stop("osmium failed:\n", paste(res, collapse = "\n"))
  }
  invisible(out)
}

# `osmium extract` arguments for an sf/sfc polygon (any CRS) or a lon/lat bbox
osmium_area_args <- function(boundary) {
  if (inherits(boundary, c("sf", "sfc"))) {
    poly <- tempfile(fileext = ".geojson")
    geom <- sf::st_geometry(boundary) |>
      sf::st_transform(4326) |>
      sf::st_make_valid() |>
      sf::st_union()
    sf::st_write(sf::st_sf(geometry = geom), poly, driver = "GeoJSON",
                 quiet = TRUE)
    c("-p", shQuote(poly))
  } else {
    bb <- as.numeric(boundary)
    stopifnot(length(bb) == 4)
    c("-b", paste(bb, collapse = ","))
  }
}

#' @param pbf      path to the .osm.pbf file
#' @param osmium   command used to call osmium (character vector: program + args)
#' @param filter   osmium tags-filter expression selecting the relations
#' @param boundary optional area to keep: an sf/sfc polygon (any CRS) or a
#'                 bbox (`sf::st_bbox()` or c(xmin, ymin, xmax, ymax) in
#'                 lon/lat). A relation is kept if any of its members lies
#'                 inside, so restrictions crossing the edge are kept whole.
#' @param tags     relation tags to keep as columns in `relations`
#' @return list with
#'   relations: one row per relation (osm_id + selected tags)
#'   members:   one row per member (relation_id, seq, member_type,
#'              member_id, role, and lon/lat for node members)
oe_restriction_members <- function(
    pbf,
    osmium = "osmium",
    filter = "r/type=restriction*",
    boundary = NULL,
    tags = c("type", "restriction", "restriction:hgv", "restriction:bus",
             "restriction:conditional", "except", "day_on", "day_off",
             "hour_on", "hour_off")) {
  stopifnot(file.exists(pbf))
  opl <- tempfile(fileext = ".opl")
  on.exit(unlink(opl), add = TRUE)
  opl_format <- c("-f", "opl,add_metadata=false")

  # Without -R osmium also writes the referenced members (and the nodes of
  # member ways), so via-node coordinates are available and the result can
  # still be clipped spatially
  filter_args <- c("tags-filter", shQuote(normalizePath(pbf)), shQuote(filter))

  if (is.null(boundary)) {
    run_osmium(osmium, c(filter_args, opl_format), opl)
  } else {
    # Filtering first shrinks a country PBF to ~1 MB, so the spatial
    # extract afterwards is almost free
    small <- tempfile(fileext = ".osm.pbf")
    on.exit(unlink(small), add = TRUE)
    run_osmium(osmium, filter_args, small)

    run_osmium(osmium, c("extract", osmium_area_args(boundary), shQuote(small),
                         opl_format), opl)
  }

  lines <- readLines(opl, encoding = "UTF-8")
  obj_type <- substr(lines, 1, 1)

  # Node coordinates: "n123 T... x1.53 y42.50"
  nd <- lines[obj_type == "n"]
  nodes <- data.frame(
    member_id = as.numeric(sub("^n(\\d+).*", "\\1", nd)),
    lon = as.numeric(sub(".* x([-0-9.]*).*", "\\1", nd)),
    lat = as.numeric(sub(".* y([-0-9.]*).*", "\\1", nd))
  )

  # Relations: "r123 Tk=v,k=v Mw1@from,n2@via,w3@to"
  rel <- lines[obj_type == "r" & grepl(" Ttype=restriction|,type=restriction", lines)]
  rel_id <- as.numeric(sub("^r(\\d+).*", "\\1", rel))
  tag_str <- ifelse(grepl(" T", rel), sub(".* T(\\S*).*", "\\1", rel), "")
  mem_str <- ifelse(grepl(" M", rel), sub(".* M(\\S*).*", "\\1", rel), "")

  # Tags -> wide table
  kv <- opl_split(tag_str)
  rel_tags <- data.frame(
    osm_id = rep(rel_id, lengths(kv)),
    key = opl_unescape(sub("=.*", "", unlist(kv))),
    value = opl_unescape(sub("^[^=]*=", "", unlist(kv)))
  )
  relations <- data.frame(osm_id = rel_id)
  for (k in tags) {
    sel <- rel_tags[rel_tags$key == k, ]
    relations[[k]] <- sel$value[match(relations$osm_id, sel$osm_id)]
  }

  # Members -> long table, keeping their order within the relation
  mm <- opl_split(mem_str)
  m <- unlist(mm)
  members <- data.frame(
    relation_id = rep(rel_id, lengths(mm)),
    seq = sequence(lengths(mm)),
    member_type = c(n = "node", w = "way", r = "relation")[substr(m, 1, 1)],
    member_id = as.numeric(sub("^.(\\d+)@.*", "\\1", m)),
    role = opl_unescape(sub("^[^@]*@", "", m)),
    row.names = NULL
  )
  members <- merge(members, nodes, by = "member_id", all.x = TRUE, sort = FALSE)
  members$lon[members$member_type != "node"] <- NA
  members$lat[members$member_type != "node"] <- NA
  members <- members[order(members$relation_id, members$seq),
                     c("relation_id", "seq", "member_type", "member_id",
                       "role", "lon", "lat")]
  rownames(members) <- NULL

  list(relations = relations, members = members)
}

# Example -------------------------------------------------------------------
if (FALSE) {
  library(osmextract)
  library(sf)

  pbf <- oe_download(oe_match("Andorra")$url,
                     download_directory = oe_download_directory())
  r <- oe_restriction_members(pbf)

  r$relations
  r$members[r$members$relation_id == 20693399, ]
  #   relation_id seq member_type member_id role ...
  #      20693399   1         way 682628184 from
  #      20693399   2        node  51399367  via
  #      20693399   3         way 274816512   to

  # One row per restriction with from / via / to ids side by side
  # (via can also be one or more ways, so it is collapsed)
  wide <- do.call(rbind, lapply(split(r$members, r$members$relation_id), function(d) {
    data.frame(
      relation_id = d$relation_id[1],
      from = paste(d$member_id[d$role == "from"], collapse = ";"),
      via_type = paste(unique(d$member_type[d$role == "via"]), collapse = ";"),
      via = paste(d$member_id[d$role == "via"], collapse = ";"),
      to = paste(d$member_id[d$role == "to"], collapse = ";")
    )
  }))
  wide <- merge(r$relations[, c("osm_id", "restriction", "except")], wide,
                by.x = "osm_id", by.y = "relation_id")

  # Member ways join straight onto the osmextract network by osm_id,
  # no spatial matching needed
  net <- oe_get_network("Andorra", mode = "driving")
  from_ways <- net[net$osm_id %in% as.character(r$members$member_id[r$members$role == "from"]), ]

  # Via nodes as points
  via_nodes <- st_as_sf(r$members[r$members$role == "via" & r$members$member_type == "node", ],
                        coords = c("lon", "lat"), crs = 4326)

  # Big PBF, small study area: pass the same boundary used for the network.
  # The whole of Colombia (~330 MB) takes a few seconds either way.
  # (the Nominatim polygon has a hole outside its shell; GDAL rejects it as is)
  bogota <- osmdata::getbb("Bogota, Colombia", format_out = "sf_polygon") |>
    st_make_valid()
  net_bog <- oe_get_network("Colombia", mode = "driving", boundary = bogota,
                            boundary_type = "clipsrc")
  r_bog <- oe_restriction_members(oe_find("Colombia", return_gpkg = FALSE),
                                  boundary = bogota)

  # Optionally keep only restrictions whose from and to ways are in the network
  in_net <- r_bog$members$member_id %in% as.numeric(net_bog$osm_id) &
    r_bog$members$member_type == "way"
  ok <- tapply(in_net | !r_bog$members$role %in% c("from", "to"),
               r_bog$members$relation_id, all)
  r_bog$relations <- r_bog$relations[r_bog$relations$osm_id %in% names(ok)[ok], ]
  r_bog$members <- r_bog$members[r_bog$members$relation_id %in% r_bog$relations$osm_id, ]
}
